package storage
import("context";"bytes";"os";"path/filepath";"testing";"github.com/alxkirshenbaum-hue/empire451f/controlpanel/internal/vault")
func portableSourceFixture(t *testing.T)(string,*Registry,string){
 t.Helper();_,r,_:=snapshotFixture(t);run:=id();if _,e:=r.db.Exec("INSERT INTO legacy_migration_runs(id,phase,source_hashes,started_at,status) VALUES(?,'verified_cutover','{}','now','verified_cutover')",run);e!=nil{t.Fatal(e)}
 for _,login:=range []string{"Alex","alex"}{q:=request;q.Login=login;rec,e:=r.QueueCreate(ctx,"owner",id(),q);if e!=nil{t.Fatal(e)};if e=r.ApplyCreate(ctx,rec,func(_ context.Context,_ string,_ vault.PlainSecret)error{return nil});e!=nil{t.Fatal(e)}}
 if _,e:=r.db.Exec("UPDATE users SET status='disabled' WHERE login='alex'");e!=nil{t.Fatal(e)}
 cap,e:=r.CaptureSnapshot(ctx,captureParent(t),"");if e!=nil{t.Fatal(e)};return cap.Path,r,run
}
func portableDestinationFixture(t *testing.T)*Registry{t.Helper();dir:=captureParent(t);v,_:=vault.New(bytes.Repeat([]byte{63},32));r,e:=Open(ctx,filepath.Join(dir,"state.db"),v,1);if e!=nil{t.Fatal(e)};t.Cleanup(func(){r.Close()});if _,e=r.db.Exec("INSERT INTO admin_accounts VALUES('fresh-owner','fresh-owner','retained-hash',0,'now',NULL)");e!=nil{t.Fatal(e)};return r}
func TestPortableIndependentDestination(t *testing.T){
 path,source,run:=portableSourceFixture(t);source.db.SetMaxOpenConns(2);before,e:=os.ReadFile(path);if e!=nil{t.Fatal(e)};dest:=portableDestinationFixture(t)
 plan,e:=dest.PreviewPortable(ctx,path,source.vault,run,"");if e!=nil{t.Fatal(e)};var count int;dest.db.QueryRow("SELECT count(*) FROM users").Scan(&count);if count!=0{t.Fatal("preview wrote users")}
 if _,e=dest.ImportPortable(ctx,path,source.vault,run,"",plan.Hash,true);e!=nil{t.Fatal(e)}
 rows,e:=source.db.Query("SELECT id,login,status,kind,protected FROM users ORDER BY id");if e!=nil{t.Fatal(e)};defer rows.Close();for rows.Next(){var uid,login,status,kind string;var protected int;if e=rows.Scan(&uid,&login,&status,&kind,&protected);e!=nil{t.Fatal(e)};var dl,ds,dk string;var dp int;if e=dest.db.QueryRow("SELECT login,status,kind,protected FROM users WHERE id=?",uid).Scan(&dl,&ds,&dk,&dp);e!=nil||dl!=login||ds!=status||dk!=kind||dp!=protected{t.Fatal("identity/status mismatch",e)};a,e:=portableSecret(t,source,uid);if e!=nil{t.Fatal(e)};b,e:=portableSecret(t,dest,uid);if e!=nil||!bytes.Equal(a,b){t.Fatal("secret mismatch",e)};clear(a);clear(b)}
 var owner string;if e=dest.db.QueryRow("SELECT password_hash FROM admin_accounts WHERE id='fresh-owner'").Scan(&owner);e!=nil||owner!="retained-hash"{t.Fatal("owner overwritten",e)}
 var links int;dest.db.QueryRow("SELECT count(*) FROM user_profiles").Scan(&links);if links!=3{t.Fatal("profile links lost",links)}
 after,e:=os.ReadFile(path);if e!=nil||!bytes.Equal(before,after){t.Fatal("source changed",e)}
 if _,e=dest.PreviewPortable(ctx,path,source.vault,run,"");e==nil{t.Fatal("occupied destination accepted")}
}
func TestPortableRejectsWrongKeyAndStalePlan(t *testing.T){path,source,run:=portableSourceFixture(t);dest:=portableDestinationFixture(t);wrong,_:=vault.New(bytes.Repeat([]byte{44},32));if _,e:=dest.PreviewPortable(ctx,path,wrong,run,"");e==nil{t.Fatal("wrong key accepted")};plan,e:=dest.PreviewPortable(ctx,path,source.vault,run,"");if e!=nil{t.Fatal(e)};if _,e=dest.db.Exec("UPDATE admin_accounts SET password_hash='changed'");e!=nil{t.Fatal(e)};if _,e=dest.ImportPortable(ctx,path,source.vault,run,"",plan.Hash,true);e==nil{t.Fatal("stale plan accepted")};var n int;dest.db.QueryRow("SELECT count(*) FROM users").Scan(&n);if n!=0{t.Fatal("failed import wrote users")}}
func portableSecret(t *testing.T,r *Registry,uid string)([]byte,error){t.Helper();var sv,kv uint64;var n,c []byte;e:=r.db.QueryRow("SELECT c.secret_version,c.key_version,c.nonce,c.ciphertext FROM credentials c JOIN user_current_credentials u ON u.credential_id=c.id WHERE u.user_id=?",uid).Scan(&sv,&kv,&n,&c);if e!=nil{return nil,e};return r.vault.Decrypt(vault.Binding{UserID:uid,SecretVersion:sv,KeyVersion:kv},n,c)}
func TestPortablePublicInitialization(t *testing.T){path,source,run:=portableSourceFixture(t);dest:=portableDestinationFixture(t);body,e:=os.ReadFile("../../../templates/sfa-profile.json");if e!=nil{t.Fatal(e)};if _,e=dest.InstallInitialSFA(ctx,body,digest(body));e!=nil{t.Fatal(e)};if _,e=dest.PreviewPortable(ctx,path,source.vault,run,"");e!=nil{t.Fatal("real clean registry preview rejected",e)}}
